tape( 'the function performs the matrix-matrix operation `op(A) * X = alpha * B` (row-major, column-major, left, lower, no-transpose, non-unit)', function test( t ) {
	var expected;
	var data;
	var out;
	var a;
	var b;

	data = racbllntanu;

	a = new Float64Array( data.A );
	b = new Float64Array( data.B );

	expected = new Float64Array( data.B_out );

	out = dtrmm( data.side, data.uplo, data.transA, data.diag, data.M, data.N, data.alpha, a, data.strideA1, data.strideA2, data.offsetA, b, data.strideB1, data.strideB2, data.offsetB );
	t.strictEqual( out, b, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

